-- Import for Gracia (gracia-lb9yze). Generated from clients/gracia-lb9yze.json; safe to re-run.
insert into companies (slug, name, contact_first_name, greeting_name, intro_basis, email_known, direction_shape, offer_text, unlock_mode, show_scarcity, is_internal)
values ('gracia-lb9yze', 'Gracia', 'Georgii', 'Georgii', 'your 4DGS streaming and PortAventura work, and the questions producers ask before they book a capture', true, to_jsonb('1 long-form article + 2 short insights'::text), null, 'call', false, false)
